def glom_cli(target, spec, indent, debug, inspect, scalar):
    try:
        val = glom.glom(target, spec)
    except GlomError as g:
        if debug:
            import pdb; pdb.post_mortem()
        raise SystemExit(1)

    if inspect:
        Inspect(val)
        return

    if scalar and is_scalar(val):
        print(val)
    else:
        import pprint
        if indent == 0:
            print(repr(val))
